mapper.delete:
DELETE FROM app.est_dans
WHERE equipe_id = #{equipeId}
  AND cip = #{memberCip}

mapper.select:
SELECT ed.cip
FROM app.est_dans ed
WHERE ed.equipe_id = #{equipeId}
  AND ed.cip != #{excludeCip}
ORDER BY ed.date_ajout ASC, ed.cip ASC
LIMIT 1

SELECT COUNT(*)
FROM app.est_dans
WHERE equipe_id = #{equipeId}

SELECT EXISTS(
    SELECT 1 FROM app.est_dans
    WHERE equipe_id = #{equipeId}
      AND cip = #{cip}
)
